fn apply_command(sim : Simulator, workflow : Workflow, command : Command) : Result(Simulator, String) =
  match command of
    Start(id) =>
      if any(\(run) -> run.id == id, sim.runs) then Err("DUPLICATE_RUN")
      else
        let run = RunState { id = id, status = Active, cancel_requested = false,
          steps = map(\(definition) -> new_step(sim.now, definition), workflow.steps) }
        Ok(Simulator { ..sim, runs = append(sim.runs, [run]) })
    Tick(None) => Ok(tick(sim, workflow))
    Advance(by) =>
      if sim.now + by > time_limit() then Err("TIME_OVERFLOW")
      else Ok(Simulator { ..sim, now = sim.now + by })
    Observe => Ok(Simulator { ..sim, observations = append(sim.observations, [snapshot(sim)]) })
    _ => Err("UNSUPPORTED_FEATURE")

fn simulate(workflow : Workflow) : Result(Simulator, String) =
  if any(\(step) -> step.failures > 0, workflow.steps) then Err("UNSUPPORTED_FEATURE")
  else run_commands(new_simulator(), workflow, workflow.commands)

fn tick(sim : Simulator, workflow : Workflow) : Simulator =
  match select_action(sim, workflow) of
    None => sim
    Some(action) =>
      let running =
        if action.step.status == Pending then
          StepState { ..action.step, status = Running, attempts = action.step.attempts + 1 }
        else action.step
      let begun_run = replace_step(action.run, running)
      let begun = replace_run(sim, begun_run)
      let key = ActionKey { run_id = action.run.id, step_id = running.id }
      let service = execute(begun.service, key, action.definition.amount, running.attempts)
      let completed = replace_step(begun_run, StepState { ..running, status = Succeeded })
      let finished =
        if all(\(step) -> step.status == Succeeded, completed.steps) then
          RunState { ..completed, status = Completed }
        else completed
      replace_run(Simulator { ..begun, service = service }, finished)

